/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = ("import React from 'react'\nimport {\n  Page,\n  Container,\n  Typography,\n  Table,\n  Helpbox,\n  PageHead,\n} from '@toptal/picasso'\nimport { SPACING_4 } from '@toptal/picasso/utils'\nimport { Section } from '@toptal/picasso'\nimport { Globe16, Profile16, PortfolioDesigner16 } from '@toptal/picasso-icons'\n\nconst SidebarMenu = () => (\n  <Page.Sidebar>\n    <Page.Sidebar.Menu>\n      <Page.Sidebar.Item icon={<PortfolioDesigner16 />}>Home</Page.Sidebar.Item>\n      <Page.Sidebar.Item icon={<Profile16 />}>Contacts</Page.Sidebar.Item>\n      <Page.Sidebar.Item icon={<Globe16 />}>Team</Page.Sidebar.Item>\n    </Page.Sidebar.Menu>\n  </Page.Sidebar>\n)\n\nconst MainContent = () => (\n  <Page.Article>\n    <PageHead>\n      <PageHead.Main>\n        <PageHead.Title>Profile</PageHead.Title>\n      </PageHead.Main>\n    </PageHead>\n    <Section title='Details'>\n      <Container bottom={SPACING_4}>\n        <Typography variant='heading' size='small'>\n          UI/UX Designer\n        </Typography>\n        <Typography size='small'>Posted at: Nov 24, 2019</Typography>\n      </Container>\n      <Table>\n        <Table.Body>\n          <Table.Row key='talent'>\n            <Table.Cell>\n              <Typography variant='heading' size='small'>\n                Talent:\n              </Typography>\n            </Table.Cell>\n            <Table.Cell>Hugo, John, Dean</Table.Cell>\n          </Table.Row>\n          <Table.Row key='commitment'>\n            <Table.Cell>\n              <Typography variant='heading' size='small'>\n                Commitment:\n              </Typography>\n            </Table.Cell>\n            <Table.Cell>Hourly</Table.Cell>\n          </Table.Row>\n        </Table.Body>\n      </Table>\n    </Section>\n    <Section title='Notes'>\n      <Helpbox>\n        <Helpbox.Title>Incomplete profile</Helpbox.Title>\n        <Helpbox.Content>\n          Talent's profile is incomplete. Please fill in required fields.\n        </Helpbox.Content>\n      </Helpbox>\n    </Section>\n  </Page.Article>\n)\n\nconst Example = () => (\n  <div style={{ height: '40rem' }}>\n    <Page>\n      <Page.TopBar title='How to layout a page' />\n      <Page.Content>\n        <SidebarMenu />\n        <MainContent />\n      </Page.Content>\n      <Page.Footer />\n    </Page>\n  </div>\n)\n\nexport default Example\n");

