/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = ("import React, { useState } from 'react'\nimport { AvatarUpload, Container } from '@toptal/picasso'\nimport { SPACING_6 } from '@toptal/picasso-utils'\nimport type { FileRejection } from '@toptal/picasso/AvatarUpload'\n\nconst Example = () => {\n  const [uploading, setUploading] = useState<boolean>(false)\n  const [src, setSrc] = useState<string | undefined>()\n\n  const handleDrop = (\n    acceptedFile: File | null,\n    fileRejection: FileRejection | null\n  ) => {\n    if (acceptedFile) {\n      // simulate upload\n      const reader = new FileReader()\n\n      reader.readAsDataURL(acceptedFile)\n\n      reader.onload = () => {\n        setUploading(true)\n\n        setTimeout(() => {\n          setUploading(false)\n\n          // simulate upload success\n          setSrc(reader.result as string)\n        }, 1000)\n      }\n\n      reader.onerror = error => {\n        console.log('Error: upload failed, ', error)\n      }\n    } else if (fileRejection) {\n      // file rejected\n      console.log(fileRejection.errors.join(', '))\n    }\n  }\n\n  return (\n    <Container padded={SPACING_6}>\n      <AvatarUpload\n        alt='Jacqueline Roque. Pablo Picasso, 1954'\n        onDrop={handleDrop}\n        src={src}\n        uploading={uploading}\n      />\n    </Container>\n  )\n}\n\nexport default Example\n");

