/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = ("import React from 'react'\nimport {\n  MemoryRouter as Router,\n  Link as RouterLink,\n  Route,\n  Switch,\n  Redirect,\n  useLocation,\n} from 'react-router-dom'\nimport { Container, Logo, Link, Breadcrumbs } from '@toptal/picasso'\nimport { SPACING_4 } from '@toptal/picasso-utils'\n\nconst Usa = () => <h2>USA</h2>\nconst Software = () => <h2>Software</h2>\nconst Toptal = () => (\n  <Container top={SPACING_4}>\n    <Logo />\n  </Container>\n)\n\nconst items = [\n  { text: 'USA', to: '/usa' },\n  { text: 'Software', to: '/usa/software' },\n  { text: 'Toptal', to: '/usa/software/toptal' },\n]\n\nconst ExampleLink: typeof Link = props => (\n  <Link as={RouterLink} variant='action' {...props} />\n)\n\nconst Nav = () => {\n  const location = useLocation()\n  const activeIndex = items.map(item => item.to).indexOf(location.pathname)\n\n  return (\n    <Breadcrumbs>\n      {items.map((item, itemIndex) => (\n        <Breadcrumbs.Item\n          as={ExampleLink}\n          key={item.text}\n          to={item.to}\n          active={itemIndex === activeIndex}\n        >\n          {item.text}\n        </Breadcrumbs.Item>\n      ))}\n    </Breadcrumbs>\n  )\n}\n\nconst Example = () => (\n  <Container>\n    <Router>\n      <Nav />\n      <Switch>\n        <Redirect exact from='/' to='/usa/software/toptal' />\n        <Route path='/usa/software/toptal'>\n          <Toptal />\n        </Route>\n        <Route path='/usa/software'>\n          <Software />\n        </Route>\n        <Route path='/usa'>\n          <Usa />\n        </Route>\n      </Switch>\n    </Router>\n  </Container>\n)\n\nexport default Example\n");

