/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = ("import React from 'react'\nimport { Container } from '@toptal/picasso'\nimport { SPACING_4 } from '@toptal/picasso-utils'\nimport {\n  FormNonCompound,\n  Input,\n  NumberInput,\n  SubmitButton,\n} from '@toptal/picasso-forms'\n\nconst minMaxValidator = (value?: string | number) => {\n  if (value === undefined) {\n    return undefined\n  }\n\n  const number = Number(value)\n\n  if (number < 0) {\n    return \"Age can't be negative\"\n  }\n\n  if (number > 120) {\n    return \"Age can't have value more than 120 years\"\n  }\n\n  return undefined\n}\n\nconst CustomValidatorExample = () => (\n  <FormNonCompound\n    onSubmit={values => window.alert(JSON.stringify(values, undefined, 2))}\n  >\n    <Input\n      required\n      name='customValidator-userName'\n      label='First name'\n      placeholder='e.g. Bruce'\n    />\n    <NumberInput\n      required\n      validate={minMaxValidator}\n      name='customValidator-userAge'\n      label=\"What's your age?\"\n      placeholder='e.g. 25'\n    />\n\n    <Container top={SPACING_4}>\n      <SubmitButton>Submit</SubmitButton>\n    </Container>\n  </FormNonCompound>\n)\n\nexport default CustomValidatorExample\n");

