/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = ("import React, { useState } from 'react'\nimport {\n  QueryBuilder,\n  type RuleType,\n  type ValidationResult,\n  type RuleGroupTypeAny,\n} from '@toptal/picasso-query-builder'\nimport { Typography } from '@toptal/picasso'\n\nconst initialQuery: RuleGroupTypeAny = {\n  rules: [\n    {\n      field: 'name',\n      operator: '=',\n      valueSource: 'value',\n      value: '',\n    },\n    {\n      field: 'age',\n      operator: '=',\n      valueSource: 'value',\n      value: '12',\n    },\n  ],\n  combinator: 'and',\n}\n\nconst checkRequired = (rule: RuleType): ValidationResult | boolean => {\n  return (\n    !!rule.value || {\n      reasons: ['Name is required'],\n      valid: false,\n    }\n  )\n}\n\nconst checkAge = (rule: RuleType): ValidationResult | boolean => {\n  return (\n    rule.value >= 18 || {\n      reasons: ['Age should be greater or equal to 18'],\n      valid: false,\n    }\n  )\n}\n\nconst fields = [\n  {\n    name: 'name',\n    label: 'Name',\n    type: 'text',\n    validator: checkRequired,\n  },\n  {\n    name: 'age',\n    label: 'Age',\n    type: 'number',\n    validator: checkAge,\n  },\n]\n\nconst Example = () => {\n  const [query, setQuery] = useState<RuleGroupTypeAny>(initialQuery)\n  const [isValid, setIsValid] = useState<boolean>(true)\n\n  const handleQueryChange = (newQuery: RuleGroupTypeAny) => {\n    setQuery(newQuery)\n  }\n\n  const handleValidationChange = (valid: boolean) => {\n    setIsValid(valid)\n  }\n\n  return (\n    <>\n      <QueryBuilder\n        fields={fields}\n        query={query}\n        onQueryChange={handleQueryChange}\n        onValidationChange={handleValidationChange}\n      />\n      <Typography>Is query valid: {isValid.toString()}</Typography>\n    </>\n  )\n}\n\nexport default Example\n");

